<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ArrowRight, CalendarDays, ChevronDown, Copy, Download, KeyRound, LoaderCircle, RefreshCw, Wifi } from 'lucide-vue-next';
import { usePanelContext } from '../composables/panelContext';
import { quotaUsed, rawPeriodUsed } from '../lib/quota';
import { t } from '../i18n';
import PageHeading from '../components/PageHeading.vue';
import ConnectionGuide from '../components/member/ConnectionGuide.vue';
import UsageDetails from '../components/UsageDetails.vue';
import NodeSubscriptionCards from '../NodeSubscriptionCards.vue';
import '../styles/member-ui.css';
const route = useRoute();
const { state, busy, sub, subUser, format, subProtocol, subSource, qr, qrError, subLoading, subError, owner, publicSubPage, userStatus, subURL, bytes, date, confirmUser, loadSub, copy, downloadSub } = usePanelContext();
const connectOpen = ref(!!route.query.connect), advancedOpen = ref(false), guide = ref<HTMLElement|null>(null);
const usagePercent = computed(() => sub.value?.user.quota ? Math.min(100, Math.max(0, quotaUsed(sub.value.user) / sub.value.user.quota * 100)) : 0);
const remainingDays = computed(() => sub.value?.user.expires ? Math.max(0, Math.ceil((sub.value.user.expires - Date.now() / 1000) / 86400)) : null);
const queuedRemainingDays = (slot: { expires: number; paused_at: number }) => slot.expires && slot.paused_at ? Math.max(0, Math.ceil((slot.expires - slot.paused_at) / 86400)) : 0;
const queuedExpiry = (slot: { expires: number; paused_at: number }) => slot.expires ? Math.floor(Date.now() / 1000) + Math.max(0, slot.expires - slot.paused_at) : 0;
const serviceMessage = computed(() => {
  if (!sub.value) return '';
  if (sub.value.active) return sub.value.nodes.length ? t('套餐已生效，选择客户端即可开始使用。') : t('套餐已生效，连接配置正在准备。可刷新或联系管理员。');
  if (!sub.value.user.entitlement) return t('还没有可用套餐，选择套餐后即可开始连接。');
  if (!sub.value.user.enabled) return t('账户当前已停用，请联系管理员。');
  if (sub.value.user.expires && remainingDays.value === 0) return t('套餐已到期，续费或选择新套餐后恢复使用。');
  if (sub.value.user.quota && quotaUsed(sub.value.user) >= sub.value.user.quota) return t('本周期流量已用尽，请等待额度重置或查看其他套餐。');
  return t('当前服务暂不可用，请查看套餐状态或联系管理员。');
});
async function startConnection() {
  connectOpen.value = true;
  await nextTick();
  guide.value?.scrollIntoView({ block: 'start', behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
  guide.value?.focus({ preventScroll: true });
}
watch(() => route.query.connect, value => { if (value) connectOpen.value = true; });
</script>
<template>
  <section v-if="state" class="member-page subscription-page">
    <PageHeading :title="owner?t('订阅管理'):t('我的服务')" :description="owner?t('套餐决定订阅内容与账号有效期。'):t('查看套餐与用量，开始你的下一次连接。')" eyebrow="MY SERVICE"><template #actions><select v-if="owner" v-model="subUser" :aria-label="t('订阅成员')"><option v-for="u in state.users" :key="u.id" :value="u.id">{{u.username}}</option></select><button :disabled="subLoading" @click="loadSub(true)"><RefreshCw :size="16" :class="{spin:subLoading}"/>{{t('刷新')}}</button></template></PageHeading>
    <div v-if="owner" class="member-hint subscription-admin-filter"><label>{{t('订阅包含范围')}}<select v-model="subSource"><option v-if="!publicSubPage" value="mixed">{{t('混合订阅（优先）')}}</option><option v-if="!publicSubPage" value="local">{{t('本站本地节点')}}</option><option v-if="!publicSubPage" value="subsite">{{t('子站节点池（挂载）')}}</option><option v-if="publicSubPage" value="public">{{t('公共节点')}}</option></select></label><p>{{t('套餐决定账号额度、有效期和节点组；混合订阅按节点组过滤全部已授权来源。')}}</p></div>
    <p v-if="subError" class="error member-feedback" role="alert">{{t(subError)}}<button :disabled="subLoading" @click="loadSub(true)">{{t('重试')}}</button></p>
    <div v-if="subLoading&&!sub" class="member-empty" role="status"><LoaderCircle :size="25" class="spin"/><p>{{t('正在读取订阅节点…')}}</p></div>
    <template v-if="sub">
      <div class="service-overview">
        <article class="member-panel service-plan"><header><div><span class="member-label">{{t('当前套餐')}}<template v-if="owner"> · {{sub.user.username}}</template></span><h2>{{sub.user.entitlement?.name||t('暂无套餐')}}</h2></div><span :class="['member-status',sub.active?'active':'failed']">{{userStatus(sub.user)}}</span></header><div class="service-start"><button class="primary" @click="startConnection">{{t('开始连接')}}<ArrowRight :size="17"/></button></div><div class="service-metrics"><div><span class="member-label">{{t('已用流量')}}</span><div class="member-metric">{{bytes(quotaUsed(sub.user))}}<small> / {{sub.user.quota?bytes(sub.user.quota):t('不限')}}</small></div><div v-if="sub.user.quota" class="plan-progress" role="progressbar" :aria-label="t('配额用量')" :aria-valuenow="Math.round(usagePercent)" :aria-valuemin="0" :aria-valuemax="100"><span :style="{width:usagePercent+'%'}"/></div><p class="member-label">{{t('下次重置')}} · {{sub.user.meter?.end?date(sub.user.meter.end):t('不自动重置')}}</p></div><div><span class="member-label">{{t('剩余有效期')}}</span><div class="member-metric">{{remainingDays===null?t('永久有效'):remainingDays}}<small v-if="remainingDays!==null"> {{t('天')}}</small></div><p class="member-label">{{t('到期时间')}} · {{date(sub.user.expires)}}</p></div></div><p class="service-message">{{serviceMessage}}</p><div v-if="owner&&sub.user.entitlement" class="plan-meta"><span>{{t('套餐版本')}} · v{{sub.user.entitlement.version}}</span><span>{{t('节点组')}} · {{sub.user.entitlement.group_ids.length}}</span><span>{{t('单独节点')}} · {{sub.user.entitlement.node_ids?.length||0}}</span></div></article>
        <aside class="member-panel service-connect"><span class="connect-symbol"><Wifi :size="25"/></span><h2>{{t('连接你的设备')}}</h2><p>{{t('选好客户端，复制订阅地址，即可开始连接。')}}</p><button :disabled="!subURL||busy" @click="copy(subURL)"><Copy :size="16"/>{{t('复制订阅地址')}}</button><RouterLink class="member-link" :to="owner?'/clients':'/shop'">{{owner?t('客户端中心'):t('查看其他套餐')}}<ArrowRight :size="15"/></RouterLink></aside>
      </div>
      <div v-if="sub.user.plan_queue?.length" class="member-hint plan-queue"><CalendarDays :size="20"/><div><strong>{{t('待恢复套餐')}}</strong><p v-for="slot in [...sub.user.plan_queue].reverse()" :key="slot.entitlement.revision"><b>{{slot.entitlement.name}}</b> · {{t('剩余有效期')}} {{slot.expires?queuedRemainingDays(slot):t('不限')}}{{slot.expires?t('天'):''}} · {{t('当前套餐结束后恢复')}}<span v-if="owner"> · {{slot.expires?date(queuedExpiry(slot)):t('不限')}}</span></p></div></div>
      <section v-if="connectOpen" ref="guide" class="member-panel service-guide" tabindex="-1"><div class="member-panel-title"><div><h2>{{t('开始连接')}}</h2><p>{{t('只需三步，把服务带到你的设备。')}}</p></div><button @click="connectOpen=false">{{t('收起')}}</button></div><ConnectionGuide :subscription-url="sub.url" :active="sub.active" :initial-platform="String(route.query.platform||'')" :initial-client="String(route.query.client||'')" @copy="copy"/></section>
      <details class="member-panel service-details" :open="advancedOpen" @toggle="advancedOpen=($event.target as HTMLDetailsElement).open"><summary><div><strong>{{t('订阅选项与连接详情')}}</strong><p>{{t('手动选择格式、协议，查看节点和流量明细。')}}</p></div><ChevronDown :size="18"/></summary><div class="service-details-body"><div class="subscription-layout"><div class="subscription-controls"><div class="member-tabs" role="group" :aria-label="t('订阅格式')"><button v-for="f in [{id:'mihomo',name:'Mihomo'},{id:'base64',name:'Base64'},{id:'raw',name:t('原始链接')}]" :key="f.id" :aria-pressed="format===f.id" @click="format=f.id">{{f.name}}</button></div><label>{{t('协议')}}<select v-model="subProtocol"><option value="">{{t('全部协议')}}</option><option value="vless">VLESS</option><option value="hy2">Hysteria2</option></select></label><label>{{t('订阅地址')}}<div class="copy-field"><input :value="subURL" readonly :aria-label="t('订阅地址')" @focus="($event.target as HTMLInputElement).select()"/><button class="icon" :aria-label="t('复制订阅地址')" :disabled="!subURL" @click="copy(subURL)"><Copy :size="17"/></button></div></label><div class="member-actions"><button :disabled="!sub.active||busy" @click="downloadSub"><Download :size="17"/>{{t('下载订阅')}}</button><button :disabled="!subURL" @click="copy(subURL)"><Copy :size="17"/>{{t('复制地址')}}</button></div><p class="member-label">{{(state.runtime?.mode==='no_logs'||state.runtime?.subscription_access_enabled===false)?(sub.user.last_sub?t('最近记录 ')+date(sub.user.last_sub,true)+' · ':'')+t('访问时间已停止记录'):sub.user.last_sub?t('最近访问 ')+date(sub.user.last_sub,true):t('尚未访问')}}</p></div><div class="qr-area"><img v-if="qr" :src="qr" width="200" height="200" :alt="t('当前订阅地址二维码')"/><p v-else-if="qrError" class="error" role="alert">{{qrError}}</p><LoaderCircle v-else :size="24" class="spin"/><span>{{format==='mihomo'?'Mihomo':format==='base64'?'Base64':'URI'}} · {{t('订阅')}}</span></div></div><div class="member-hint"><span>{{t('实际周期流量')}} · {{bytes(rawPeriodUsed(sub.user))}}</span></div><UsageDetails :user="sub.user"/><NodeSubscriptionCards :key="sub.user.id+':'+sub.pool+':'+subProtocol" :nodes="sub.nodes" :active="sub.active" :pool="sub.pool" :loading="subLoading" @refresh="loadSub()"/></div></details>
      <div v-if="owner" class="member-panel subscription-security"><h2>{{t('凭据管理')}}</h2><div class="member-actions"><button @click="confirmUser(sub.user,'rotate-all-sub')"><RefreshCw :size="16"/>{{t('重置订阅地址')}}</button><button class="danger-button" @click="confirmUser(sub.user,'revoke')"><KeyRound :size="16"/>{{t('撤销全部旧配置')}}</button></div></div>
    </template>
  </section>
</template>
<style scoped>
.service-overview{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:20px}.service-plan{border-top:3px solid var(--accent)}.service-start{display:flex;gap:12px;margin-top:20px}.service-start>.primary{min-height:44px;min-width:150px;justify-content:center;font-size:14px}.service-plan>header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.service-plan h2{font-size:25px;margin:9px 0 0;overflow-wrap:anywhere}.service-plan>header>div{min-width:0}.service-plan>header>.member-status{flex-shrink:0}.service-metrics{display:grid;grid-template-columns:1.25fr 1fr;gap:28px;margin:24px 0 20px}.service-metrics p{margin:12px 0 0;font-size:12px}.service-metrics>div+div{border-left:1px solid var(--border);padding-left:28px}.service-metrics .member-metric{font-size:31px;margin-top:8px}.plan-progress{height:6px;background:var(--border);border-radius:8px;overflow:hidden;margin-top:16px}.plan-progress span{height:100%;display:block;border-radius:8px;background:var(--accent)}.service-message{font-size:13px;line-height:1.8;color:var(--secondary);border-top:1px solid var(--border);padding-top:17px;margin:0}.service-connect{display:flex;flex-direction:column;gap:10px}.connect-symbol{width:42px;height:42px;display:grid;place-items:center;background:var(--accent-soft);border-radius:12px;color:var(--accent-text);margin-bottom:5px}.service-connect h2{font-size:19px;margin:0}.service-connect p{font-size:13px;color:var(--secondary);line-height:1.8;margin:0 0 6px}.service-connect>button{justify-content:center}.service-connect>button{margin-top:auto}.plan-meta{display:flex;flex-wrap:wrap;gap:7px 20px;margin-top:15px;color:var(--secondary);font-size:12px}.plan-queue strong{display:block;color:var(--text);margin-bottom:5px}.plan-queue p{margin:4px 0}.plan-queue b{font-weight:550}.service-guide{scroll-margin-top:24px}.service-guide:focus{outline:none}.service-guide:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.service-details>summary{display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer;list-style:none;min-height:44px}.service-details>summary::-webkit-details-marker{display:none}.service-details>summary strong{font-size:15px}.service-details>summary p{font-size:13px;line-height:1.7;color:var(--secondary);margin:7px 0 0}.service-details[open]>summary>svg{transform:rotate(180deg)}.service-details-body{display:grid;gap:20px;margin-top:25px;padding-top:23px;border-top:1px solid var(--border)}.subscription-admin-filter{align-items:center;flex-wrap:wrap}.subscription-admin-filter label{display:flex;gap:12px;align-items:center;flex-shrink:0}.subscription-admin-filter p{flex:1;min-width:200px}.subscription-layout{display:grid;grid-template-columns:minmax(0,1fr) 220px;gap:32px;padding:0;background:none;border:0}.subscription-controls{display:flex;flex-direction:column;gap:17px;min-width:0}.subscription-controls label{display:flex;flex-direction:column;gap:8px}.subscription-controls select{max-width:260px}.copy-field{display:flex}.copy-field input{min-width:0;flex:1}.copy-field button{flex-shrink:0}.qr-area{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;border:1px solid var(--border);border-radius:12px;padding:15px;background:var(--surface-raised);font-size:13px;color:var(--secondary)}.qr-area img{max-width:100%;height:auto;background:#fff;border-radius:6px}.subscription-security{display:flex;align-items:center;justify-content:space-between;gap:20px}.subscription-security h2{margin:0}.subscription-page :deep(.usage-details){margin:0}.subscription-page :deep(.subscription-nodes){margin:0;border-radius:12px}.subscription-page :deep(.subscription-node-card h3){font-size:14px}.subscription-page :deep(.subscription-node-card>footer button),.subscription-page :deep(.subscription-nodes-tools button){font-size:13px;min-height:44px}@media(max-width:1050px){.service-overview{grid-template-columns:1fr}.service-connect{display:grid;grid-template-columns:1fr 1fr;align-items:center}.service-connect .connect-symbol{display:none}.service-connect h2,.service-connect p{grid-column:1/-1}.service-connect>button{margin:0}.service-connect>.member-link{grid-column:auto}}@media(max-width:650px){.service-start{margin-top:18px}.service-start>.primary{width:100%}.service-metrics{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;margin:22px 0 18px}.service-metrics>div{min-width:0}.service-metrics>div+div{padding-left:16px}.service-metrics .member-metric{font-size:23px;letter-spacing:-.5px;overflow-wrap:anywhere}.service-metrics>div:first-child .member-metric small{display:block;margin-top:4px;font-size:12px;letter-spacing:0}.service-metrics p{font-size:12px;margin-top:9px;overflow-wrap:anywhere}.service-metrics .plan-progress{margin-top:12px}.service-message{padding-top:14px}.service-plan h2{font-size:23px}.subscription-layout{grid-template-columns:1fr}.qr-area{width:230px;max-width:100%;box-sizing:border-box;justify-self:center}.subscription-security{flex-direction:column;align-items:flex-start}.subscription-admin-filter label{align-items:flex-start;flex-direction:column;width:100%}.subscription-admin-filter select,.subscription-controls select{width:100%;max-width:none}.service-details>summary p{font-size:12px}}
</style>
